import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { join, extname, normalize } from "node:path";
import { fileURLToPath } from "node:url";
import { randomUUID } from "node:crypto";

import { ensureScheme, isPlausibleUrl, findDuplicate, hostOf } from "../public/logic.js";
import { fetchPageInfo } from "./pageinfo.js";

const __dirname = fileURLToPath(new URL(".", import.meta.url));
const PUBLIC_DIR = join(__dirname, "..", "public");

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
};

function send(res, status, body, headers = {}) {
  const payload = typeof body === "string" || Buffer.isBuffer(body) ? body : JSON.stringify(body);
  res.writeHead(status, { "Content-Type": "application/json; charset=utf-8", ...headers });
  res.end(payload);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = "";
    req.on("data", (c) => {
      data += c;
      if (data.length > 1_000_000) reject(new Error("body too large"));
    });
    req.on("end", () => {
      if (!data) return resolve({});
      try {
        resolve(JSON.parse(data));
      } catch (e) {
        reject(new Error("invalid json"));
      }
    });
    req.on("error", reject);
  });
}

async function serveStatic(res, urlPath) {
  let rel = decodeURIComponent(urlPath.split("?")[0]);
  if (rel === "/" || rel === "") rel = "/index.html";
  const safe = normalize(rel).replace(/^(\.\.[/\\])+/, "");
  const filePath = join(PUBLIC_DIR, safe);
  if (!filePath.startsWith(PUBLIC_DIR)) return send(res, 403, { error: "forbidden" });
  try {
    const buf = await readFile(filePath);
    const type = MIME[extname(filePath).toLowerCase()] || "application/octet-stream";
    res.writeHead(200, { "Content-Type": type });
    res.end(buf);
  } catch (e) {
    // SPA fallback to index.html for unknown non-API GETs
    try {
      const buf = await readFile(join(PUBLIC_DIR, "index.html"));
      res.writeHead(200, { "Content-Type": MIME[".html"] });
      res.end(buf);
    } catch (e2) {
      send(res, 404, { error: "not found" });
    }
  }
}

function newLink(url, info) {
  const ok = !!(info && info.ok && info.title);
  return {
    id: randomUUID(),
    url,
    host: hostOf(url),
    title: ok ? info.title : "",
    description: info && info.description ? info.description : "",
    note: "",
    tags: [],
    inList: false,
    autoFailed: !ok,
    savedAt: Date.now(),
  };
}

// Whitelist of fields a client may patch, with light validation (SCN-002/003/004/006).
function sanitizePatch(patch) {
  const out = {};
  if (typeof patch.title === "string") out.title = patch.title.trim();
  if (typeof patch.description === "string") out.description = patch.description.trim();
  if (typeof patch.note === "string") out.note = patch.note.trim();
  if (typeof patch.inList === "boolean") out.inList = patch.inList;
  if (Array.isArray(patch.tags)) {
    const seen = [];
    for (const t of patch.tags) {
      const s = String(t || "").trim().toLowerCase().replace(/^#+/, "").trim();
      if (s && seen.indexOf(s) === -1) seen.push(s);
    }
    out.tags = seen;
  }
  return out;
}

export function createApp({ store, fetchInfo }) {
  const getInfo = fetchInfo || ((url) => fetchPageInfo(url));

  return async function handler(req, res) {
    try {
      const { method } = req;
      const url = req.url || "/";
      const path = url.split("?")[0];

      if (path === "/api/links" && method === "GET") {
        return send(res, 200, { links: store.all() });
      }

      if (path === "/api/links" && method === "POST") {
        let body;
        try {
          body = await readBody(req);
        } catch (e) {
          return send(res, 400, { error: "invalid", message: "Could not read the request." });
        }
        const raw = String(body.url || "").trim();
        if (!raw) {
          return send(res, 400, { error: "empty", message: "Please paste a link first." });
        }
        if (!isPlausibleUrl(raw)) {
          return send(res, 400, {
            error: "invalid",
            message: "That doesn't look like a web address. Check the link and try again.",
          });
        }
        const normalized = ensureScheme(raw);
        const dup = findDuplicate(store.all(), normalized);
        if (dup) {
          return send(res, 409, { error: "duplicate", link: dup });
        }
        const info = await getInfo(normalized);
        const link = newLink(normalized, info);
        await store.add(link);
        return send(res, 201, { link });
      }

      const idMatch = path.match(/^\/api\/links\/([^/]+)$/);
      if (idMatch) {
        const id = decodeURIComponent(idMatch[1]);
        if (method === "PATCH") {
          let body;
          try {
            body = await readBody(req);
          } catch (e) {
            return send(res, 400, { error: "invalid" });
          }
          const patch = sanitizePatch(body);
          const updated = await store.update(id, patch);
          if (!updated) return send(res, 404, { error: "not found" });
          return send(res, 200, { link: updated });
        }
        if (method === "DELETE") {
          const ok = await store.remove(id);
          if (!ok) return send(res, 404, { error: "not found" });
          return send(res, 204, "");
        }
      }

      if (path.startsWith("/api/")) {
        return send(res, 404, { error: "not found" });
      }

      if (method === "GET") {
        return serveStatic(res, url);
      }

      return send(res, 405, { error: "method not allowed" });
    } catch (e) {
      return send(res, 500, { error: "server error" });
    }
  };
}

export function createHttpServer(opts) {
  return createServer(createApp(opts));
}
// Simple durable storage for the single personal user: a JSON file on disk.
// No database is prescribed; this keeps the collection persistent across restarts
// while staying dependency-free.

import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";

export class Store {
  constructor(filePath) {
    this.filePath = filePath;
    this.links = [];
    this._loaded = false;
    this._writing = Promise.resolve();
  }

  async load() {
    try {
      const raw = await readFile(this.filePath, "utf8");
      const data = JSON.parse(raw);
      this.links = Array.isArray(data.links) ? data.links : [];
    } catch (e) {
      this.links = [];
    }
    this._loaded = true;
    return this.links;
  }

  async _persist() {
    await mkdir(dirname(this.filePath), { recursive: true });
    const body = JSON.stringify({ links: this.links }, null, 2);
    // serialise writes to avoid interleaving
    this._writing = this._writing.then(() => writeFile(this.filePath, body, "utf8"));
    return this._writing;
  }

  all() {
    return this.links;
  }

  get(id) {
    return this.links.find((l) => l.id === id) || null;
  }

  async add(link) {
    this.links.push(link);
    await this._persist();
    return link;
  }

  async update(id, patch) {
    const link = this.get(id);
    if (!link) return null;
    Object.assign(link, patch);
    await this._persist();
    return link;
  }

  async remove(id) {
    const before = this.links.length;
    this.links = this.links.filter((l) => l.id !== id);
    const removed = this.links.length < before;
    if (removed) await this._persist();
    return removed;
  }
}
// Reads a page's title and description from its address (SCN-001). Server-side,
// so there is no browser CORS restriction. On any failure the caller falls back
// to SCN-006 behaviour (save anyway, show the address, let the user fill in).

function decode(s) {
  if (s == null) return "";
  return s
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&nbsp;/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function metaContent(html, patterns) {
  for (const re of patterns) {
    const m = html.match(re);
    if (m && m[1]) {
      const v = decode(m[1]);
      if (v) return v;
    }
  }
  return "";
}

export function parsePageInfo(html) {
  if (!html) return { title: "", description: "" };
  const head = html.slice(0, 200000); // titles/meta live near the top
  const title =
    metaContent(head, [
      /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i,
      /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:title["']/i,
    ]) ||
    (function () {
      const m = head.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
      return m ? decode(m[1]) : "";
    })();
  const description = metaContent(head, [
    /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i,
    /<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i,
    /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i,
    /<meta[^>]+content=["']([^"']*)["'][^>]+property=["']og:description["']/i,
  ]);
  return { title, description };
}

// Fetches and parses page info. Returns { title, description, ok }.
// Never throws; a failure yields ok:false with empty fields (SCN-006).
export async function fetchPageInfo(url, { timeoutMs = 4000, fetchImpl = globalThis.fetch } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetchImpl(url, {
      signal: controller.signal,
      redirect: "follow",
      headers: {
        "User-Agent": "Mozilla/5.0 (compatible; BookmarkApp/1.0)",
        Accept: "text/html,application/xhtml+xml",
      },
    });
    if (!res || !res.ok) return { title: "", description: "", ok: false };
    const ctype = (res.headers.get("content-type") || "").toLowerCase();
    if (ctype && !ctype.includes("html") && !ctype.includes("xml")) {
      return { title: "", description: "", ok: false };
    }
    const html = await res.text();
    const info = parsePageInfo(html);
    return { title: info.title, description: info.description, ok: !!info.title };
  } catch (e) {
    return { title: "", description: "", ok: false };
  } finally {
    clearTimeout(timer);
  }
}
// Shared, pure domain logic — usable in the browser (type="module") and in Node
// tests / server. No DOM, no I/O. This is the single source of truth for the
// behavioural rules approved in SCN-001..009.

export function ensureScheme(raw) {
  const u = String(raw || "").trim();
  if (!u) return "";
  return /^https?:\/\//i.test(u) ? u : "https://" + u;
}

export function hostOf(raw) {
  const u = ensureScheme(raw);
  try {
    return new URL(u).hostname.replace(/^www\./i, "").toLowerCase();
  } catch (e) {
    return String(raw || "")
      .replace(/^https?:\/\//i, "")
      .split("/")[0]
      .replace(/^www\./i, "")
      .toLowerCase();
  }
}

// A "plausible web address" (SCN-008): a domain-like host with a dot and a
// 2+ character final label. Rejects plain text like "dinner ideas".
export function isPlausibleUrl(raw) {
  const u = ensureScheme(raw);
  let host;
  try {
    host = new URL(u).hostname;
  } catch (e) {
    return false;
  }
  if (/\s/.test(host)) return false;
  return /^[^\s.]+(\.[^\s.]+)*\.[a-z]{2,}$/i.test(host);
}

// Normalised address for duplicate comparison (SCN-008): scheme-normalised,
// lower-cased, trailing slashes removed.
export function normalizeUrl(raw) {
  const u = ensureScheme(raw);
  try {
    const p = new URL(u);
    p.hostname = p.hostname.replace(/^www\./i, "").toLowerCase();
    p.protocol = p.protocol.toLowerCase();
    let s = p.toString();
    return s.replace(/\/+$/, "").toLowerCase();
  } catch (e) {
    return u.replace(/\/+$/, "").toLowerCase();
  }
}

export function findDuplicate(links, raw) {
  const target = normalizeUrl(raw);
  return links.find((l) => normalizeUrl(l.url) === target) || null;
}

export function normalizeTag(raw) {
  return String(raw || "").trim().toLowerCase().replace(/^#+/, "").trim();
}

// Returns a NEW tag array with the tag added (deduped). SCN-002.
export function addTag(tags, raw) {
  const t = normalizeTag(raw);
  const list = Array.isArray(tags) ? tags.slice() : [];
  if (t && list.indexOf(t) === -1) list.push(t);
  return list;
}

export function removeTag(tags, raw) {
  const t = normalizeTag(raw);
  return (Array.isArray(tags) ? tags : []).filter((x) => x !== t);
}

// All tag names in use across the collection, sorted (for suggestions). SCN-002.
export function allTags(links) {
  const set = new Set();
  for (const l of links) for (const t of l.tags || []) set.add(t);
  return Array.from(set).sort();
}

// Text a link can be found by (SCN-005): title, description, tags, full web
// address, and the user's note.
export function haystack(link) {
  return [
    link.title || "",
    link.description || "",
    (link.tags || []).join(" "),
    link.url || "",
    link.note || "",
  ]
    .join(" ")
    .toLowerCase();
}

// Search: case-insensitive, all whitespace-separated words must be present. SCN-005.
export function matchesSearch(link, q) {
  const query = String(q || "").trim().toLowerCase();
  if (!query) return true;
  const hay = haystack(link);
  return query.split(/\s+/).filter(Boolean).every((w) => hay.indexOf(w) !== -1);
}

// Tag filter: a link must carry ALL active tags. SCN-005.
export function matchesTags(link, tagFilters) {
  const filters = Array.isArray(tagFilters) ? tagFilters : [];
  const tags = link.tags || [];
  return filters.every((t) => tags.indexOf(t) !== -1);
}

// The visible collection for a given view + search + tag filters, newest first.
// SCN-003 (reading list view), SCN-005 (search/filter), SCN-009 (ordering).
export function visibleLinks(links, { view = "all", q = "", tagFilters = [] } = {}) {
  return links
    .filter((l) => (view === "list" ? !!l.inList : true))
    .filter((l) => matchesSearch(l, q) && matchesTags(l, tagFilters))
    .slice()
    .sort((a, b) => b.savedAt - a.savedAt);
}
